package de.ga36.home;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.provider.Settings;import android.widget.Toast;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;import java.lang.reflect.Method;
final class BackgroundTasks {
 static volatile String foreground;private static final AtomicBoolean busy=new AtomicBoolean();private static final ExecutorService worker=Executors.newSingleThreadExecutor();
 static String top(ActivityManager am){try{List<ActivityManager.RunningTaskInfo> tasks=am.getRunningTasks(1);if(tasks!=null&&!tasks.isEmpty()&&tasks.get(0).topActivity!=null)return tasks.get(0).topActivity.getPackageName();}catch(RuntimeException e){android.util.Log.w("GA36Tasks","Foreground task query unavailable",e);}return null;}
 static Set<String> running(ActivityManager am){List<ActivityManager.RunningAppProcessInfo> list=am.getRunningAppProcesses();if(list==null)throw new IllegalStateException("Process list unavailable");Set<String> packages=new HashSet<String>();for(ActivityManager.RunningAppProcessInfo p:list){if(p.pkgList!=null)Collections.addAll(packages,p.pkgList);else if(p.processName!=null)packages.add(p.processName.split(":",2)[0]);}return packages;}
 static void close(final Context context,final String protectedAtPress){if(!busy.compareAndSet(false,true))return;final Context app=context.getApplicationContext();final Handler ui=new Handler(Looper.getMainLooper());worker.execute(new Runnable(){public void run(){android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);boolean success=false;int closed=0,failed=0;try{
  for(String permission:new String[]{"android.permission.REAL_GET_TASKS","android.permission.FORCE_STOP_PACKAGES"})if(app.checkCallingOrSelfPermission(permission)!=PackageManager.PERMISSION_GRANTED)throw new SecurityException("Required permission unavailable: "+permission);
  ActivityManager am=(ActivityManager)app.getSystemService(Context.ACTIVITY_SERVICE);String active=top(am);if(active==null||active.isEmpty())throw new IllegalStateException("Active app unknown; refusing cleanup");
  Set<String> protect=new HashSet<String>();protect.add(active);if(protectedAtPress!=null)protect.add(protectedAtPress);String ime=Settings.Secure.getString(app.getContentResolver(),Settings.Secure.DEFAULT_INPUT_METHOD);if(ime!=null&&ime.contains("/"))protect.add(ime.substring(0,ime.indexOf('/')));
  PackageManager pm=app.getPackageManager();Set<Integer> protectedIds=new HashSet<Integer>();protectedIds.add(android.os.Process.myUid());for(String p:protect)try{protectedIds.add(pm.getApplicationInfo(p,0).uid);}catch(PackageManager.NameNotFoundException ignored){}
  Set<String> live=running(am),attempted=new HashSet<String>(),stopped=new HashSet<String>();Method stop=ActivityManager.class.getMethod("forceStopPackage",String.class);
  for(ApplicationInfo info:pm.getInstalledApplications(0)){String current=top(am);if(current==null||current.isEmpty())throw new IllegalStateException("Lost foreground task; aborting cleanup");protect.add(current);try{protectedIds.add(pm.getApplicationInfo(current,0).uid);}catch(PackageManager.NameNotFoundException e){throw new IllegalStateException(e);}
   if(!live.contains(info.packageName)||protectedIds.contains(info.uid)||!BackgroundPolicy.eligible(info.packageName,info.flags,protect)||!attempted.add(info.packageName))continue;
   try{stop.invoke(am,info.packageName);stopped.add(info.packageName);}catch(Exception e){failed++;android.util.Log.w("GA36Tasks","Cannot stop "+info.packageName,e);}
  }
  Set<String> remaining=running(am);for(int retry=0;retry<4&&!Collections.disjoint(stopped,remaining);retry++){SystemClock.sleep(75);remaining=running(am);}
  for(String p:stopped){if(remaining.contains(p)){failed++;android.util.Log.w("GA36Tasks","Process still present: "+p);}else closed++;}
  success=failed==0;android.util.Log.i("GA36Tasks","BACKGROUND_CLOSED verified="+closed+" failed="+failed+" foreground_protected="+active);
 }catch(Exception e){android.util.Log.e("GA36Tasks","BACKGROUND_CLOSE_FAILED",e);}finally{final boolean done=success;final int count=closed;busy.set(false);ui.post(new Runnable(){public void run(){if("de.ga36.home".equals(foreground))GamepadDialog.dismissVisible();Toast.makeText(app,done?(count==0?I18n.t("Keine Hintergrund-Apps aktiv"):count+I18n.t(" Hintergrund-Apps beendet")):I18n.t("Hintergrund-Apps konnten nicht vollständig beendet werden"),Toast.LENGTH_SHORT).show();}});}}});}
}
